INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38711, 'Genesis 25:33', 'Genesis', 25, 33, 'خو یعقوب وویل: «لومړی ماته قسم وخوره.» نو هغه قسم وخوړ او خپل د مشرتوب حق یې په یعقوب باندې خرڅ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_33.mp3', '', 1761754199, 1761754199),
(38712, 'Genesis 25:34', 'Genesis', 25, 34, 'بیا یعقوب عیسو ته لږه ډوډۍ او قورمه ورکړه. هغه خوراک او څښاک وکړ، بیا پاڅېده او لاړ. نو عیسو د خپل مشرتوب حق ته په سپکه سترګه وکتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_34.mp3', '', 1761754199, 1761754199),
(38713, 'Genesis 12:1', 'Genesis', 12, 1, 'څښتن ابرام ته وویل: «خپل وطن، خپلوان او د خپل پلار کور پرېږده او هغه هېواد ته لاړ شه چې زه یې درته ښایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_1.mp3', '', 1761754199, 1761754199),
(38714, 'Genesis 12:2', 'Genesis', 12, 2, 'زه به ستا څخه لوی قوم جوړ کړم او برکت به درکړم. ستا نوم به مشهور کړم او د نورو دپاره به د برکت سبب وګرځې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_2.mp3', '', 1761754199, 1761754199),
(38715, 'Genesis 12:3', 'Genesis', 12, 3, 'څوک چې تاته درکوي برکت زه به ورکړمه هغوی ته برکت خو څوک چې ووایي په تا باندې لعنت زه به ووایم هغوی باندې لعنت او وربه کړم ستا په وسیله برکت ټولو قومونو د دنیا ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_3.mp3', '', 1761754199, 1761754199),
(38716, 'Genesis 12:4', 'Genesis', 12, 4, 'لکه څنګه چې څښتن ابرام ته ویلي وو، هغه لاړ او لوط هم ورسره لاړ. ابرام د پنځه اویا کالو په عمر ؤ چې د حران څخه روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_4.mp3', '', 1761754199, 1761754199),
(38717, 'Genesis 12:5', 'Genesis', 12, 5, 'ابرام خپله ښځه سارای، خپل وراره لوط، خپل غلامان او هغه ټوله شتمني چې په حران کې یې پیدا کړې وه، د ځان سره واخیستل او کنعان ته روان شول. کله چې هلته ورسېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_5.mp3', '', 1761754199, 1761754199),
(38718, 'Genesis 12:6', 'Genesis', 12, 6, 'ابرام په هغې خاوره کې ګرځېده، ترڅو د موره سپېڅلې ونې ته چې هغه په شکیم کې یو پاک ځای ؤ، ورسېده. (په هغه وخت کې په هغې خاورې کې کنعانیان اوسېدل.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_6.mp3', '', 1761754199, 1761754199),
(38719, 'Genesis 12:7', 'Genesis', 12, 7, 'څښتن ابرام ته ښکاره شو او هغه ته یې وویل: «دا هغه وطن دی چې زه غواړم هغه ستا اولادې ته ورکړم.» نو ابرام په هغه ځای کې چې څښتن ورته ورښکاره شوی ؤ، د قربانۍ ځای جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_7.mp3', '', 1761754199, 1761754199),
(38720, 'Genesis 12:8', 'Genesis', 12, 8, 'بیا یې هغې غرنۍ سیمې ته کډه وکړه چې د لمرپرېواته خوا څخه بیت‌ییل او د لمرخاته خوا څخه عای ته رسیږي. ابرام په هغه ځای کې خپلې خېمې ودرولې او هلته یې د قربانۍ ځای جوړ کړ او د څښتن عبادت یې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_8.mp3', '', 1761754199, 1761754199),
(38721, 'Genesis 12:9', 'Genesis', 12, 9, 'بیا هغه د یو ځای څخه بل ځای ته کډه کوله او د کنعان جنوب خواته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_9.mp3', '', 1761754199, 1761754199),
(38722, 'Genesis 12:10', 'Genesis', 12, 10, 'خو په کنعان کې قحطي راغله او هغه دومره سخته شوه چې ابرام مصر ته لاړ چې هلته د لږ وخت دپاره واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_10.mp3', '', 1761754199, 1761754199),
(38723, 'Genesis 12:11', 'Genesis', 12, 11, 'کله چې هغه د مصر سرحد ته ورنژدې شو، خپلې ښځې سارای ته یې وویل: «ته ښایسته ښځه یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_11.mp3', '', 1761754199, 1761754199),
(38724, 'Genesis 12:12', 'Genesis', 12, 12, 'کله چې مصریان تا وویني، وبه وایي: ‹دا د هغه ښځه ده.› نو دوی به ما ووژني او تا به ژوندۍ پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_12.mp3', '', 1761754199, 1761754199),
(38725, 'Genesis 12:13', 'Genesis', 12, 13, 'هغوی ته ووایه چې ته زما خور یې، نو ستا په خاطر به هغوی زما سره ښه چلند وکړي او ما به ژوندی پرېږدي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_13.mp3', '', 1761754199, 1761754199),
(38726, 'Genesis 12:14', 'Genesis', 12, 14, 'کله چې هغه مصر ته ورننوت، مصریانو ولیدل چې د هغه ښځه ډېره ښایسته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_14.mp3', '', 1761754199, 1761754199),
(38727, 'Genesis 12:15', 'Genesis', 12, 15, 'کله چې د فرعون درباریانو هغه ولیدله، هغوی د فرعون په مخکې د هغې صفت وکړ او هغه یې د فرعون ماڼۍ ته وروستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_15.mp3', '', 1761754199, 1761754199),
(38728, 'Genesis 12:16', 'Genesis', 12, 16, 'فرعون د هغې په خاطر د ابرام سره ښه چلند وکړ او هغه ته یې رمې او پادې، خره او خرې، اوښان، وینځې او غلامان ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_16.mp3', '', 1761754199, 1761754199),
(38729, 'Genesis 12:17', 'Genesis', 12, 17, 'خو څښتن فرعون او د هغه درباریان د ابرام د ښځې سارای په سبب په خطرناکو ناروغیو باندې اخته کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_17.mp3', '', 1761754199, 1761754199),
(38730, 'Genesis 12:18', 'Genesis', 12, 18, 'نو فرعون ابرام راوغوښت او د هغه څخه یې پوښتنه وکړه: «زما سره دې څه وکړل؟ ولې دې ماته ونه ویل چې هغه ستا ښځه ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_18.mp3', '', 1761754199, 1761754199),
(38731, 'Genesis 12:19', 'Genesis', 12, 19, 'ولې دې وویل چې هغه ستا خور ده، کېدای شو چې ما د هغې سره واده کړی وای؟ ګوره، دا ستا ښځه ده. هغه واخله او لاړ شه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_19.mp3', '', 1761754199, 1761754199),
(38732, 'Genesis 12:20', 'Genesis', 12, 20, 'فرعون خپلو کسانو ته حکم وکړ چې ابرام او د هغه ښځه د هر هغه څه سره چې درلودل یې، ولېږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis12_verse_20.mp3', '', 1761754199, 1761754199),
(38733, 'Psalms 138:1', 'Psalms', 138, 1, 'د زړه د اخلاصه دې وباسم شکر ای څښتنه نورو خدایانو مخکې زه وایم ستا د ثنا سندره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_1.mp3', '', 1761754199, 1761754199),
(38734, 'Psalms 138:2', 'Psalms', 138, 2, 'کوم سجده ستا د سپېڅلي کور په لور او ثنا او صفت دې د نامه کومه ستا د تلپاتې مینې او وفادارۍ په خاطر ځکه خپل نوم او خپل کلام دې کړ اوچت ټولو شیانو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_2.mp3', '', 1761754199, 1761754199),
(38735, 'Psalms 138:3', 'Psalms', 138, 3, 'چې کله سوال درته ما کړی قبول کړی دی تا په خپل قدرت دې قوي کړی یم زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_3.mp3', '', 1761754199, 1761754199),
(38736, 'Psalms 138:4', 'Psalms', 138, 4, 'د نړۍ ټول پاچاهان به ستا ستاینه کوي ای څښتنه په دې خاطر چې ستا کلام دی اورېدلی هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_4.mp3', '', 1761754199, 1761754199),
(38737, 'Psalms 138:5', 'Psalms', 138, 5, 'وایي سندرې به هغوی هغو کارو په هکله کوم چې کړي دي تا ځکه چې لوی دی ستا جلال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_5.mp3', '', 1761754199, 1761754199),
(38738, 'Psalms 138:6', 'Psalms', 138, 6, 'سره له دې چې ډېر عظیم یې ته خو پام کوې په عاجزانو باندې خو کبرجن خلک ته پېژنې له لېرې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_6.mp3', '', 1761754199, 1761754199),
(38739, 'Psalms 138:7', 'Psalms', 138, 7, 'کله چې زه لاس او ګرېوان یم تکلیفونو سره ته مې خوندي ساتې ته ودرېږې زما د قهرجنو دښمنانو مخې ته او بچ کوې مې ته په خپل قوي لاسونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_7.mp3', '', 1761754199, 1761754199),
(38740, 'Psalms 138:8', 'Psalms', 138, 8, 'ته به سرته رسوې خپل مقصد زما دپاره ده ابدي ستا مینه ای څښتنه تا پیدا کړي یو او مونږ مه پرېږده ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms138_verse_8.mp3', '', 1761754199, 1761754199),
(38741, 'Jeremiah 25:1', 'Jeremiah', 25, 1, 'يرمياه ته د يهوداه بادشاه د يوسياه د زوئ يهويقيم د بادشاهۍ په څلورم کال، د يهوداه د ټولو خلقو په حقله د مالِک خُدائ د طرف نه پېغام ورکړے شو. په هم دغه کال باندې نبوکدنضر د بابل په تخت کښېناستو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_1.mp3', '', 1761754199, 1761754199),
(38742, 'Jeremiah 25:2', 'Jeremiah', 25, 2, 'نو بيا يرمياه نبى د يروشلم ټولو اوسېدونکو او د يهوداه ټول قوم ته بيان وکړو او ورته يې وفرمائيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_2.mp3', '', 1761754199, 1761754199),
(38743, 'Jeremiah 25:3', 'Jeremiah', 25, 3, '”د يهوداه بادشاه د امون د زوئ يوسياه د بادشاهۍ د ديارلسم کال نه واخله، تر اوسه پورې مالِک خُدائ د درويشتو کالو دپاره ما ته پېغام راکړو او ما هغه تاسو ته څو ځله در رسولے دے، خو تاسو ما ته غوږ ونۀ نيولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_3.mp3', '', 1761754199, 1761754199),
(38744, 'Jeremiah 25:4', 'Jeremiah', 25, 4, 'سره د دې چې مالِک خُدائ بيا بيا خپل خِدمتګاران پېغمبران رالېږلى دى، تاسو هغوئ ته نۀ غوږ نيولو او نۀ مو هغوئ ته توجو ورکوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_4.mp3', '', 1761754199, 1761754199),
(38745, 'Jeremiah 25:5', 'Jeremiah', 25, 5, 'هغوئ به تاسو ته فرمائيل چې، تاسو هر يو خپلې خرابې طريقې او هغه بد کارونه پرېږدئ کوم چې تاسو کوئ، نو بيا تاسو په هغه مُلک کښې تر تله پورې اوسېدلے شئ کوم چې ما تاسو او ستاسو پلار نيکۀ له ورکړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_5.mp3', '', 1761754199, 1761754199),
(38746, 'Jeremiah 25:6', 'Jeremiah', 25, 6, 'هغوئ به تاسو ته فرمائيل چې د نورو معبودانو عبادت او خِدمت مۀ کوئ، تاسو چې په خپلو لاسونو کوم بُتان جوړ کړى دى هغوئ ته په عبادت کولو زما قهر مۀ راپاروئ. نو بيا به زۀ تاسو ته نقصان نۀ درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_6.mp3', '', 1761754199, 1761754199),
(38747, 'Jeremiah 25:7', 'Jeremiah', 25, 7, 'مالِک خُدائ وفرمائيل چې، خو تاسو ما ته غوږ ونۀ نيولو، او تاسو چې څۀ جوړ کړى وُو د هغې په وجه تاسو زۀ په قهر او غصه کړم، او تاسو په خپله خپل ځان ته نقصان ورسولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_7.mp3', '', 1761754199, 1761754199),
(38748, 'Jeremiah 25:8', 'Jeremiah', 25, 8, 'نو په دې وجه مالِک خُدائ ربُ الافواج داسې فرمائى چې، ځکه چې تاسو زما پېغام ته غوږ ونۀ نيولو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_8.mp3', '', 1761754199, 1761754199),
(38749, 'Jeremiah 25:9', 'Jeremiah', 25, 9, 'زۀ به د شمال ټول خلق او خپل خدمتګار د بابل بادشاه نبوکدنضر د دې مُلک او په دې کښې د اوسېدونکو خلقو او د خواوشا ټولو قومونو په خلاف د جنګ دپاره راولېږم. زۀ به هغوئ بلکل تباه کړم او هغوئ به د خلقو دپاره د يرې دهشت، ټوقو، او مسخرو يو مثال وګرځوم، او په ابدى کنډرو به يې بدل کړم. مالِک خُدائ دا فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_9.mp3', '', 1761754199, 1761754199),
(38750, 'Jeremiah 25:10', 'Jeremiah', 25, 10, 'زۀ به د هغوئ د خندا او د خوشحالۍ چغې د دې ځائ نه خاموش کړم او زۀ به د هغوئ د وادۀ د ناوې او د زلمى د خوشحالۍ آوازونه خاموش کړم. د هغوئ د مېچونو آوازونه به خاموش کړم او د هغوئ ډيوې به مړې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_10.mp3', '', 1761754199, 1761754199),
(38751, 'Jeremiah 25:11', 'Jeremiah', 25, 11, 'دا ټول مُلک به په شاړو او خرابو باندې بدل شى، او دا قومونه به د اويا کالونو دپاره د بابل د بادشاه خِدمت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_11.mp3', '', 1761754199, 1761754199),
(38752, 'Jeremiah 25:12', 'Jeremiah', 25, 12, 'خو چې کله اويا کالونه پوره شى، نو بيا به زۀ د بابل بادشاه او د هغۀ قوم، او د هغۀ مُلک له سزا ورکړم، د هغوئ د هغه ګناهونو په وجه کوم چې هغوئ کړى دى، مالِک خُدائ دا فرمائى، او د تل دپاره به د بابل مُلک په دشته او خرابه بدل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_12.mp3', '', 1761754199, 1761754199),
(38753, 'Jeremiah 25:13', 'Jeremiah', 25, 13, 'زۀ به په دې مُلک هغه ټول افتونه راولم کوم چې ما د دۀ خلاف بيان کړى دى، او په دې کِتاب کښې ليکلے شوى دى او کوم چې د يرمياه نبى په ذريعه د ټولو قومونو خلاف پېشګوئې شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_13.mp3', '', 1761754199, 1761754199),
(38754, 'Jeremiah 25:14', 'Jeremiah', 25, 14, 'نور ډېر قومونه او غټ بادشاهان به هغوئ غلامان جوړ کړى، او زۀ به هغوئ ته هم هغه شان سزا ورکړم کومه سزا چې هغوئ نورو ته ورکړې وه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_14.mp3', '', 1761754199, 1761754199),
(38755, 'Jeremiah 25:15', 'Jeremiah', 25, 15, 'مالِک خُدائ چې د بنى اِسرائيلو خُدائ پاک دے ما ته يې وفرمائيل، ”زما د لاس نه دا پيالۍ واخله چې زما د غضب د شرابو نه ډکه ده او ټولو قومونو ته چې زۀ تا استوم په هغوئ يې وڅښوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_15.mp3', '', 1761754199, 1761754199),
(38756, 'Jeremiah 25:16', 'Jeremiah', 25, 16, 'کله چې هغوئ دا وڅښى، نو هغوئ ټول به زنګيږى او تيندکونه به خورى او کوم جنګ چې زۀ په دوئ باندې راولم د هغې په وجه به ليونى شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_16.mp3', '', 1761754199, 1761754199),
(38757, 'Jeremiah 25:17', 'Jeremiah', 25, 17, 'نو بيا ما د مالِک خُدائ د لاس نه پيالۍ واخستله او په هغه ټولو قومونو مې وڅښله چې زۀ چا ته هغۀ ورلېږلے وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_17.mp3', '', 1761754199, 1761754199),
(38758, 'Jeremiah 25:18', 'Jeremiah', 25, 18, 'زۀ يروشلم او د يهوداه ټولو ښارونو او د هغوئ بادشاهانو او مشرانو له لاړم او هغوئ ټولو د غضب د پيالۍ نه وڅښل. د هغه وخت نه تر اوسه پورې، دا مُلک تباه شو، او د هغوئ دپاره د يرې او دهشت، ټوقو مسخرو شو او خلقو د هغوئ په نومونو لعنت وئيلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_18.mp3', '', 1761754199, 1761754199),
(38759, 'Jeremiah 25:19', 'Jeremiah', 25, 19, 'ما دا پيالۍ فِرعون د مِصر بادشاه او د هغۀ نوکرانو او آفسرانو له او ټولو مِصريانو له ورکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_19.mp3', '', 1761754199, 1761754199),
(38760, 'Jeremiah 25:20', 'Jeremiah', 25, 20, 'او نورو ټولو هغه پردو خلقو ته څوک چې په دې مُلک کښې اوسېدل، او د عُوض ټولو بادشاهانو ته، د فلستيه د ټولو ښارونو بادشاهانو ته لکه اسقلون، غزه، عقرون، او کوم خلق چې په اشدود کښې پاتې وُو ورکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_20.mp3', '', 1761754199, 1761754199),
(38761, 'Jeremiah 25:21', 'Jeremiah', 25, 21, 'د ادوم، موآب او عمون قومونه ته،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_21.mp3', '', 1761754199, 1761754199),
(38762, 'Jeremiah 25:22', 'Jeremiah', 25, 22, 'د صور او صيدا ټولو بادشاهانو ته، او د سمندر د ساحلى علاقو بادشاهانو ته،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_22.mp3', '', 1761754199, 1761754199),
(38763, 'Jeremiah 25:23', 'Jeremiah', 25, 23, 'د ددان، تيما او بُوز ښارونو او هغه ټولو خلقو ته څوک چې لرې اوسېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_23.mp3', '', 1761754199, 1761754199),
(38764, 'Jeremiah 25:24', 'Jeremiah', 25, 24, 'د عربو ټولو بادشاهانو ته او د ټولو هغه اجنبيانو بادشاهانو ته چې هلته په ريګستان کښې اوسېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_24.mp3', '', 1761754199, 1761754199),
(38765, 'Jeremiah 25:25', 'Jeremiah', 25, 25, 'د زِمرى، عيلام او د مادى ټولو بادشاهانو ته،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_25.mp3', '', 1761754199, 1761754199),
(38766, 'Jeremiah 25:26', 'Jeremiah', 25, 26, 'او ما د شمال ټولو نزدې لرې بادشاهانو ته، او پرله پسې د زمکې په مخ ټولو بادشاهتونو ته ورکړه. او د دې هر څۀ نه وروستو د بابل بادشاه به يې هم وڅښى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_26.mp3', '', 1761754199, 1761754199),
(38767, 'Jeremiah 25:27', 'Jeremiah', 25, 27, 'بيا مالِک خُدائ ما ته وفرمائيل، ”اوس هغوئ ته ووايه چې، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، تاسو وڅښئ چې نشه شئ او اولټۍ وکړئ، او چې راوغورزېږئ چې بيا هيڅکله راپورته نۀ شئ ځکه چې زۀ به په تاسو جنګ راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_27.mp3', '', 1761754199, 1761754199),
(38768, 'Jeremiah 25:28', 'Jeremiah', 25, 28, 'خو کۀ هغوئ ستا د لاس د پيالۍ اخستلو او څښلو نه اِنکار وکړى، هغوئ ته ووايه، مالِک خُدائ ربُ الافواج فرمائى چې، دا پيالۍ به ضرور څښئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_28.mp3', '', 1761754199, 1761754199),
(38769, 'Jeremiah 25:29', 'Jeremiah', 25, 29, 'ګورئ چې ما د تباهۍ کار په يروشلم کښې شروع کړلو کوم ښار چې زما په نوم ياديږى. نو ولې تاسو به د سزا نه خلاص شئ څۀ؟ تاسو به بې‌سزا پاتې نۀ شئ، ځکه چې زۀ په ټوله زمکه کښې او د هغوئ په ټولو اوسېدونکو باندې جنګ راولم، مالِک خُدائ ربُ الافواج دا فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_29.mp3', '', 1761754199, 1761754199),
(38770, 'Jeremiah 25:30', 'Jeremiah', 25, 30, 'نو اوس دا ټولې خبرې د هغوئ خلاف بيان کړه او هغوئ ته ووايه چې، مالِک خُدائ به د آسمان د اوچتو او مقدسو ځايونو نه لکه د ازمرى په شان وغړمبيږى او هغه به د خپل وطن خلاف زورَور آوازونه وکړى. او هغه به داسې په تېزه آوازونه وکړى لکه څنګه چې د انګورو نچوړونکى په هغه وخت کښې شور کوى. او هغه به د هغوئ ټولو خلاف په زوره چغې ووهى څوک چې په دُنيا کښې اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_30.mp3', '', 1761754199, 1761754199),
(38771, 'Jeremiah 25:31', 'Jeremiah', 25, 31, 'او د هغۀ د عدالت آواز به د دُنيا د يو سر نه تر بل سره پورې ورسيږى. ځکه چې مالِک خُدائ د قومونو خِلاف عدالت کوى. او هغه به د ټولو انسانانو فېصله واوروى او بدکاران به جنګونو ته حواله کړى. مالِک خُدائ دا فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_31.mp3', '', 1761754199, 1761754199),
(38772, 'Jeremiah 25:32', 'Jeremiah', 25, 32, 'ربُ الافواج داسې فرمائى چې، وګورئ، افت د يو مُلک نه بل مُلک ته پيوسته خوريږى او يو لوئ طوفان د دُنيا د بل سر نه راروان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_32.mp3', '', 1761754199, 1761754199),
(38773, 'Jeremiah 25:33', 'Jeremiah', 25, 33, 'په هغه ورځ به چې کوم خلق مالِک خُدائ وژلى وى د هغوئ لاشونه به هر چرته د دُنيا د يو سر نه تر بل سره پورې پراتۀ وى. په هغوئ باندې به نۀ څوک ماتم کوى او نۀ به يې څوک رايوځائ کولے شى او نۀ به ښخولے شى خو په زمکه به لکه د ډيران د ډيرى په شان پراتۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_33.mp3', '', 1761754199, 1761754199),
(38774, 'Jeremiah 25:34', 'Jeremiah', 25, 34, 'اے د قوم شپونکو تاسو په خپل ځان باندې ژړا او ماتم وکړئ، او اے د قومونو مشرانو تاسو په خاورو ايرو کښې ورغړېږئ. ځکه ستاسو د حلالېدلو او خورېدلو وخت رارسېدلے دے. تاسو به د خټو د نازک لوښى په شان راوغورزېږئ او ټوکړې ټوکړې به شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_34.mp3', '', 1761754199, 1761754199),
(38775, 'Jeremiah 25:35', 'Jeremiah', 25, 35, 'د شپونکو سره به د تېښتې دپاره يو ځائ هم نۀ وى، او د قوم د مشرانو سره به د منډې دپاره يو ځائ هم نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_35.mp3', '', 1761754199, 1761754199),
(38776, 'Jeremiah 25:36', 'Jeremiah', 25, 36, 'د شپونکو ژړا انګولا واورئ، او د قوم د مشرانو ژړا او فرياد واورئ، ځکه چې مالِک خُدائ د هغوئ مُلک تباه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_36.mp3', '', 1761754199, 1761754199),
(38777, 'Jeremiah 25:37', 'Jeremiah', 25, 37, 'د مالِک خُدائ د يروونکى قهر په وجه به د آرام ځايونه خراب شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_37.mp3', '', 1761754199, 1761754199),
(38778, 'Jeremiah 25:38', 'Jeremiah', 25, 38, 'مالِک خُدائ لکه د يو طاقتور ازمرى په شان کله چې د خپل غار نه راوځى او په خلقو حمله وکړى نو دغه شان به د ظالم تيره تُوره او د مالِک خُدائ سخت قهر به د هغوئ مُلک تباه کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah25_verse_38.mp3', '', 1761754199, 1761754199),
(38779, 'Jeremiah 12:1', 'Jeremiah', 12, 1, 'اے مالِکه خُدايه، تۀ همېشه ما سره اِنصاف کوې کله چې زۀ يوه مسئله ستا په حضور کښې وړاندې کړم. نو ما ته د مقدمې کولو اجازت راکړه، نو دا بدکاران ولې دومره ترقى کوى؟ او ولې ټول غداران دومره په آرام ژوند تېروى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_1.mp3', '', 1761754199, 1761754199),
(38780, 'Jeremiah 12:2', 'Jeremiah', 12, 2, 'تا هغوئ کَرلى دى او دوئ جرړې کړې دى، دا لوئ شى او مېوه ونيسى. تۀ هر وخت د هغوئ په خولۀ يې، خو د هغوئ د زړونو نه لرې يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_2.mp3', '', 1761754199, 1761754199),
(38781, 'Jeremiah 12:3', 'Jeremiah', 12, 3, 'خو اے مالِکه خُدايه، تۀ ما پېژنې، او تۀ ما وينې او تۀ په ما آزمېښت وکړه چې زۀ ستا يم. دا بدعمله خلق داسې راکاږه لکه څنګه چې يو ګډ د حلالولو دپاره راښکلے شى، او د حلالولو پورې يې يوې خوا ته وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_3.mp3', '', 1761754199, 1761754199),
(38782, 'Jeremiah 12:4', 'Jeremiah', 12, 4, 'دا زمکه به تر کومې پورې ماتم کوى او په پټو کښې به يې ګياه اوچيږى؟ څوک چې په دې مُلک کښې اوسيږى نو د هغوئ د بدعملۍ په وجه مارغان او ځناور تباه شوى دى، او هم په دې وجه خلق دا وائى چې، ”خُدائ به هم حيران وى چې مونږ سره به څۀ کيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_4.mp3', '', 1761754199, 1761754199),
(38783, 'Jeremiah 12:5', 'Jeremiah', 12, 5, 'مالِک خُدائ ورته وفرمائيل، ”اے يرمياه، کۀ چرې تۀ د انسانانو سره په منډه وهلو دومره ستړے کېږې، نو تۀ به د آسونو سره څۀ مقابله وکړې؟ کۀ چرې تۀ په يو هوار او محفوظه مېدان کښې تيندکونه خورې او راغورزېږې، نو تۀ به د اُردن سره په ګڼ ځنګل کښې څۀ کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_5.mp3', '', 1761754199, 1761754199),
(38784, 'Jeremiah 12:6', 'Jeremiah', 12, 6, 'تر دې چې ستا وروڼه، او ستا د خپل خاندان خلق ستا مخالفت کوى. هغوئ ستا خلاف شکايتونه کوى. په هغوئ باور مۀ کوه، کۀ څۀ هم چې هغوئ ستا ښۀ وائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_6.mp3', '', 1761754199, 1761754199),
(38785, 'Jeremiah 12:7', 'Jeremiah', 12, 7, 'مالِک خُدائ فرمائى، ”ما خپل خلق پرېښودل، چې زما خاص ميراث دے. ما ته ډېر ګران خلق مې د دشمنانو لاسونو ته حواله کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_7.mp3', '', 1761754199, 1761754199),
(38786, 'Jeremiah 12:8', 'Jeremiah', 12, 8, 'زما غوره شوے قوم لکه د ځنګل د زمرى په شان ما ته وغړمبېدو، نو په دې وجه زۀ د هغوئ نه نفرت کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_8.mp3', '', 1761754199, 1761754199),
(38787, 'Jeremiah 12:9', 'Jeremiah', 12, 9, 'آيا دا مُلک د ګيدړانو غار دے چې ټپوسان پرې بره الوځى رالوځى. خو ځنګلى ځناور دې راشى چې د هغوئ لاشونه وخورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_9.mp3', '', 1761754199, 1761754199),
(38788, 'Jeremiah 12:10', 'Jeremiah', 12, 10, 'ډېرو حاکمانو زما د انګورو باغونه برباد کړى دى، او هغوئ ټول بوټى د پښو لاندې کړى دى او ښائست يې ورله ختم او په بيابان بدل کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_10.mp3', '', 1761754199, 1761754199),
(38789, 'Jeremiah 12:11', 'Jeremiah', 12, 11, 'هغوئ د دې نه تش بيابان جوړ کړے دے او ما د خپلو خلقو د ماتم ژړا اورېدلې ده، او زما د ټول مُلک نه دشته بيابان جوړ شوے دے، او څوک يې هم پرواه نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_11.mp3', '', 1761754199, 1761754199),
(38790, 'Jeremiah 12:12', 'Jeremiah', 12, 12, 'د بيابان په ټولو اوچتو او خُشکو غونډو د قتل و غارت فوج ليدلے کيږى، ځکه چې د مالِک خُدائ تُوره به د يو سر نه تر بل سره پورې هغوئ هلاک کړى. نو څوک به هم محفوظ نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_12.mp3', '', 1761754199, 1761754199),
(38791, 'Jeremiah 12:13', 'Jeremiah', 12, 13, 'زما خلقو غنم وکَرل، خو تش ازغى يې ورېبل، هغوئ ډېر محنت وکړو خو هيڅ فائده يې حاصله نۀ کړه. ځکه د مالِک خُدائ د سختې غصې په وجه، هغوئ صرف د رُسوايۍ او شرم فصل ورېبلو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_13.mp3', '', 1761754199, 1761754199),
(38792, 'Jeremiah 12:14', 'Jeremiah', 12, 14, 'مالِک خُدائ فرمائى، ”زۀ به د بنى اِسرائيلو نه هغه ټول شريره او بدکاره ګاونډيان د جرړې نه راوکاږم څوک چې د هغوئ په زمکه قبضه کول غواړى، او زۀ به يهوداه هم د بنى اِسرائيلو د مينځ نه راوکاږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_14.mp3', '', 1761754199, 1761754199),
(38793, 'Jeremiah 12:15', 'Jeremiah', 12, 15, 'خو کله چې زۀ هغوئ راوباسم، نو بيا به زۀ په هغوئ باندې رحم وکړم، او زۀ به هغوئ هر يو قوم خپل ميراث او خپل مُلک ته واپس راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_15.mp3', '', 1761754199, 1761754199),
(38794, 'Jeremiah 12:16', 'Jeremiah', 12, 16, 'او بيا کۀ چرې دا قومونه په رښتيا سره زما د خلقو طريقې زده کړى، او کۀ هغوئ زما په نوم قسم خوړل زده کړى او وائى چې په يقين سره مالِک خُدائ ژوندے دے، لکه څنګه چې هغوئ يو وخت زما قوم ته د بعل د بُت په نوم قسم خوړل ور زده کړى وُو، نو هغوئ به بيا زما د قوم په مينځ کښې آباد شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_16.mp3', '', 1761754199, 1761754199),
(38795, 'Jeremiah 12:17', 'Jeremiah', 12, 17, 'خو کۀ چرې هر يو قوم زما خبرو ته غوږ ونۀ نيسى، نو بيا به زۀ هغه قوم په مکمل توګه د بېخ نه راوکاږم او نيست و نابود به يې کړم.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah12_verse_17.mp3', '', 1761754199, 1761754199),
(38796, 'Deuteronomy 30:1', 'Deuteronomy', 30, 1, 'تاسو ته مې اوس د برکت او لعنت د غوره کولو حق درکړی دی. کله چې په تاسو باندې دا ټولې پېښې وشي او تاسو د هغو قومونو په منځ کې ژوند وکړئ چې خپل څښتن خدای هلته شړلي یئ، نو زما هغه خبره به در په یاده شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_1.mp3', '', 1761754199, 1761754199),
(38797, 'Deuteronomy 30:2', 'Deuteronomy', 30, 2, 'که چېرې تاسو او ستاسو اولاده بېرته څښتن ته رجوع وکړئ او د زړه له کومي د هغه د ټولو حکمونو چې نن یې درکوم اطاعت وکړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_2.mp3', '', 1761754199, 1761754199),
(38798, 'Deuteronomy 30:3', 'Deuteronomy', 30, 3, 'بیا به خپل څښتن خدای په تاسو باندې رحم وکړي. هغه به تاسو د هغو قومونو څخه چې تاسو یې په کې خپاره کړي یئ، بېرته راولي او بېرته به مو نېکمرغه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_3.mp3', '', 1761754199, 1761754199),
(38799, 'Deuteronomy 30:4', 'Deuteronomy', 30, 4, 'حتی که تاسو د دنیا په بل سر کې هم اوسئ، ستاسو څښتن خدای به تاسو راپیدا کړي او بېرته به مو راولي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_4.mp3', '', 1761754199, 1761754199),
(38800, 'Deuteronomy 30:5', 'Deuteronomy', 30, 5, 'ترڅو ستاسو اولاده بیا هغه خاوره تر لاسه کړي چې یو وخت د هغوی نیکونه په کې اوسېدل. هغه به ستاسو اولاده د خپلو نیکونو څخه نوره هم نېکمرغه او زیاته کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_5.mp3', '', 1761754199, 1761754199),
(38801, 'Deuteronomy 30:6', 'Deuteronomy', 30, 6, 'تاسو او ستاسو اولادې ته به خپل څښتن خدای منونکي زړونه درکړي، ترڅو د زړه له کومي د هغه سره مینه وکړئ او په هغه خاوره کې خپل ژوند وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_6.mp3', '', 1761754199, 1761754199),
(38802, 'Deuteronomy 30:7', 'Deuteronomy', 30, 7, 'هغه به دا ټول لعنتونه ستاسو په دښمنانو باندې چې ستاسو څخه یې کرکه کوله او تاسو یې ځورولئ، راولي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_7.mp3', '', 1761754199, 1761754199),
(38803, 'Deuteronomy 30:8', 'Deuteronomy', 30, 8, 'او تاسو به بیا د څښتن او د هغه د ټولو حکمونو اطاعت کوئ چې زه یې نن درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_8.mp3', '', 1761754199, 1761754199),
(38804, 'Deuteronomy 30:9', 'Deuteronomy', 30, 9, 'څښتن به تاسو ته په خپلو ټولو کارونو کې زیات بریالیتوبونه درکړي. تاسو به ډېر اولادونه او حیوانات ولرئ او ستاسو پټي به پرېمانه فصلونه کوي. هغه به ستاسو په نېکمرغه کولو باندې هماغسې خوشحاله وي لکه څنګه چې ستاسو د نیکونو په نېکمرغه کولو باندې خوشحاله ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_9.mp3', '', 1761754199, 1761754199),
(38805, 'Deuteronomy 30:10', 'Deuteronomy', 30, 10, 'خو تاسو به مجبور یئ چې د څښتن اطاعت وکړئ او د هغو ټولو قوانینو څخه پیروي وکړئ چې په دې کتاب کې لیکل شوي دي. تاسو به مجبور یئ چې د زړه له کومي هغه ته رجوع وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_10.mp3', '', 1761754199, 1761754199),
(38806, 'Deuteronomy 30:11', 'Deuteronomy', 30, 11, 'هغه امرونه چې نن یې تاسو ته درکوم په هغو باندې پوهېدل او عمل کول ډېر سخت کار نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_11.mp3', '', 1761754199, 1761754199),
(38807, 'Deuteronomy 30:12', 'Deuteronomy', 30, 12, 'هغه امرونه پورته په اسمان کې نه دي، ترڅو تاسو دې ته مجبور شئ چې داسې پوښتنه وکړئ: ‹څوک به پورته وخېژي چې هغه مونږ ته لاندې راوړي، ترڅو هغه واورو او عمل ورباندې وکړو؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_12.mp3', '', 1761754199, 1761754199),
(38808, 'Deuteronomy 30:13', 'Deuteronomy', 30, 13, 'نه هغه د بحیرې په بلې غاړې باندې دي، ترڅو دې ته مجبور شئ چې داسې پوښتنه وکړئ: څوک به د بحیرې څخه تېر شي چې هغه مونږ ته راوړي، ترڅو هغه واورو او عمل ورباندې وکړو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_13.mp3', '', 1761754199, 1761754199),
(38809, 'Deuteronomy 30:14', 'Deuteronomy', 30, 14, 'نه، دا حکمونه تاسو ته نژدې دي. هغه ستاسو په خوله او ستاسو په زړونو کې دي، نو تاسو باید ورباندې عمل وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_14.mp3', '', 1761754199, 1761754199),
(38810, 'Deuteronomy 30:15', 'Deuteronomy', 30, 15, 'نن زه تاسو ته د نېکمرغۍ او بدبختۍ او ژوند او مرګ د غوره کولو حق درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_15.mp3', '', 1761754199, 1761754199);